/** Pure state reducer shared by the runtime and UI-facing run snapshots. */ function agentRunReducer(state, action) {
    if (action.type === 'replace') return {
        ...action.state,
        events: [
            ...action.state.events
        ]
    };
    if (action.type === 'append_event') return {
        ...state,
        events: [
            ...state.events,
            action.event
        ]
    };
    return {
        ...state,
        ...action.patch,
        events: action.patch.events ? [
            ...action.patch.events
        ] : [
            ...state.events
        ]
    };
}
