class ModelDiscoveryError extends Error {
    constructor(message, status){
        super(message);
        this.name = 'ModelDiscoveryError';
        this.status = status;
    }
}
function withTimeout(signal, timeoutMs) {
    const controller = new AbortController();
    const timer = globalThis.setTimeout(()=>controller.abort(new DOMException('Request timed out', 'TimeoutError')), timeoutMs);
    const clean = ()=>globalThis.clearTimeout(timer);
    controller.signal.addEventListener('abort', clean, {
        once: true
    });
    signal?.addEventListener('abort', ()=>controller.abort(signal.reason), {
        once: true
    });
    return controller.signal;
}
async function discoverModels(profile, signal, timeoutMs = 8000) {
    const url = `${normalizeBaseURL(profile.baseURL)}/models`;
    const headers = {
        Accept: 'application/json'
    };
    if (profile.apiKey.trim()) headers.Authorization = `Bearer ${profile.apiKey}`;
    let response;
    try {
        response = await fetch(url, {
            headers,
            signal: withTimeout(signal, timeoutMs)
        });
    } catch (error) {
        if (error.name === 'AbortError' || error.name === 'TimeoutError') {
            throw new ModelDiscoveryError('Model discovery timed out');
        }
        throw new ModelDiscoveryError('Unable to reach the model endpoint');
    }
    if (!response.ok) {
        // Do not surface a gateway response body: some proxies echo authorization
        // headers or request data in their error payloads.
        throw new ModelDiscoveryError(`Model discovery failed (${response.status})`, response.status);
    }
    const data = await response.json().catch(()=>null);
    if (!Array.isArray(data?.data)) throw new ModelDiscoveryError('The endpoint returned an invalid model list');
    return data.data.flatMap((item)=>{
        if (typeof item === 'string') return [
            {
                id: item
            }
        ];
        if (!item || typeof item !== 'object' || typeof item.id !== 'string') return [];
        const model = item;
        return [
            {
                id: model.id,
                ownedBy: model.owned_by,
                created: model.created,
                supportedParameters: Array.isArray(model.supported_parameters) ? model.supported_parameters.filter((v)=>typeof v === 'string') : undefined,
                contextLength: model.context_length
            }
        ];
    });
}
function filterChatModels(models) {
    return models.filter((model)=>!/embedding|rerank|moderation|whisper|tts|audio|image|vision/i.test(model.id));
}
function recommendModel(profile, models) {
    return [
        ...filterChatModels(models)
    ].sort((a, b)=>modelScore(profile, b) - modelScore(profile, a))[0] ?? null;
}
function detectToolSupport(model) {
    if (!model) return 'unknown';
    return model.supportedParameters?.includes('tools') ? 'supported' : 'unknown';
}

