function dynamicTopK(scores, minK = 3, maxK = 10) {
    if (scores.length <= minK) return Math.min(scores.length, minK);
    const avg = scores.reduce((a, b)=>a + b, 0) / scores.length;
    const significant = scores.filter((s)=>s >= avg).length;
    return Math.max(minK, Math.min(significant, maxK));
}
