function getTerminalGlyphs(text) {
    const segmenter = new Intl.Segmenter(undefined, {
        granularity: 'grapheme'
    });
    return Array.from(segmenter.segment(text), function({ segment }) {
        return segment;
    });
}
function waitForAboutDelay(ms, signal) {
    return new Promise(function(resolve, reject) {
        if (signal.aborted) {
            reject(new DOMException('Aborted', 'AbortError'));
            return;
        }
        const timer = window.setTimeout(resolve, ms);
        signal.addEventListener('abort', function() {
            window.clearTimeout(timer);
            reject(new DOMException('Aborted', 'AbortError'));
        }, {
            once: true
        });
    });
}
function waitForAboutAdvance(inputState, signal) {
    return new Promise(function(resolve, reject) {
        if (signal.aborted) {
            reject(new DOMException('Aborted', 'AbortError'));
            return;
        }
        const finish = function(error) {
            inputState.aboutWaiting = false;
            inputState.aboutAdvance = null;
            signal.removeEventListener('abort', onAbort);
            if (error) reject(error);
            else resolve();
        };
        const onAbort = function() {
            finish(new DOMException('Aborted', 'AbortError'));
        };
        inputState.aboutWaiting = true;
        inputState.aboutAdvance = function() {
            finish();
        };
        signal.addEventListener('abort', onAbort, {
            once: true
        });
    });
}
async function playAbout(context, inputState, signal, generation) {
    const paragraphs = getAboutParagraphs();
    inputState.aboutActive = true;
    try {
        for(let index = 0; index < paragraphs.length; index++){
            inputState.aboutTyping = true;
            for (const part of paragraphs[index]){
                for (const char of getTerminalGlyphs(part.text)){
                    if (signal.aborted || inputState.generation !== generation) return;
                    context.write((part.style || '') + char + ansi.X);
                    await waitForAboutDelay(30, signal);
                }
                if (part.pauseAfter) await waitForAboutDelay(part.pauseAfter, signal);
            }
            if (signal.aborted || inputState.generation !== generation) return;
            inputState.aboutTyping = false;
            if (index === paragraphs.length - 1) {
                context.writeln('');
                context.writeln(ansi.D + '── 自我介绍结束，感谢阅读。' + ansi.X);
                return;
            }
            context.writeln('');
            context.write(ansi.D + '按任意键继续…' + ansi.X);
            await waitForAboutAdvance(inputState, signal);
            context.write('\r\x1b[2K');
        }
    } finally{
        inputState.aboutActive = false;
        inputState.aboutTyping = false;
        inputState.aboutWaiting = false;
        inputState.aboutAdvance = null;
    }
}
/** Starts the interactive, cancellable self-introduction session. */ async function runAbout(context, inputState, signal, generation) {
    await playAbout(context, inputState, signal, generation);
}

