function parseCommand(input) {
    const trimmed = input.trim();
    if (!trimmed) return null;
    const tokens = trimmed.split(/\s+/);
    const args = [];
    const flags = {};
    for(let i = 1; i < tokens.length; i++){
        const token = tokens[i];
        if (token.startsWith('--')) {
            const equal = token.indexOf('=');
            flags[equal >= 0 ? token.slice(2, equal) : token.slice(2)] = equal >= 0 ? token.slice(equal + 1) : true;
        } else if (token.startsWith('-')) flags[token.slice(1)] = true;
        else args.push(token);
    }
    return {
        cmd: tokens[0].toLowerCase(),
        args,
        flags
    };
}
function getAllCategories(items) {
    const categories = new Set();
    for (const item of items)for (const category of item.categories)categories.add(category);
    return [
        ...categories
    ].sort((a, b)=>a.localeCompare(b));
}
function filterByCategory(items, category) {
    return items.filter((item)=>item.categories.some((value)=>value.toLowerCase() === category.toLowerCase()));
}
function categoryExists(items, name) {
    return items.some((item)=>item.categories.some((category)=>category.toLowerCase() === name.toLowerCase()));
}
function wordCount(text) {
    let count = 0;
    for (const character of text)if (/[\u4e00-\u9fff\u3400-\u4dbf]/.test(character)) count++;
    else if (/[a-zA-Z0-9]/.test(character)) count++;
    return count + (text.match(/[a-zA-Z]+/g)?.length || 0);
}

