class Elixir extends ItemTile {
    static{
        this.token = 'Ex';
    }
    static{
        this.identity = {
            id: ItemId.Elixir,
            name: 'Elixir'
        };
    }
    static{
        this.display = {
            color: 'cyan'
        };
    }
    static{
        this.shortcut = 'w';
    }
    static use(context) {
        if (!context.has(ItemId.Elixir)) {
            return {
                handled: false,
                movement: 'stay'
            };
        }
        const increase = context.state.attack * 5 + context.state.defense * 10;
        context.spend(ItemId.Elixir);
        context.state.hp += increase;
        context.setMessage(`Used ${context.itemName(ItemId.Elixir)}! HP was restored by ${increase} pts!`);
        return {
            handled: true,
            movement: 'stay'
        };
    }
}

