class MagicKey extends ItemTile {
    static{
        this.token = 'Mk';
    }
    static{
        this.identity = {
            id: ItemId.MagicKey,
            name: 'Magic Key'
        };
    }
    static{
        this.display = {
            color: 'yellow'
        };
    }
    static{
        this.shortcut = 'k';
    }
    static use(context) {
        if (!context.has(ItemId.MagicKey)) {
            return {
                handled: false,
                movement: 'stay'
            };
        }
        for (const tile of context.activeTiles(context.state.floor)){
            const data = tile.data;
            if (data.color === ItemId.YellowKey && data.kind === 'door') context.remove(tile);
        }
        context.spend(ItemId.MagicKey);
        context.setMessage(`Used ${this.identity.name}! All the doors were opened on this floor.`);
        return {
            handled: true,
            movement: 'stay'
        };
    }
}

