/** Apply the single game-over invariant shared by every damage source. */ function markDefeated(state, message) {
    if (state.hp <= 0) {
        state.hp = 0;
        state.over = message;
        return true;
    }
    return false;
}
/**
 * Normal battle retaliation only.
 *
 * JW/SW magic fields and the Magic Guard domain are map effects. They are not
 * part of a fight's round damage and are queued by the corresponding Tile
 * during a world update instead.
 */ function magicTowerDamage(state, monster, options = {}) {
    const attack = modifyBattleAttack(state, monster, state.attack);
    if (attack <= monster.defense) return null;
    const effectiveHp = modifyMonsterHp(state, monster, monster.hp);
    const rounds = Math.ceil(effectiveHp / (attack - monster.defense));
    const retaliation = Math.max(0, monster.attack - state.defense);
    let damage = retaliation * Math.max(0, rounds - 1);
    if (options.firstStrike) damage += retaliation;
    return damage;
}
function resolveBattle(state, context, tile, entity, monster, options = {}) {
    const damage = magicTowerDamage(state, monster, options);
    if (damage == null) {
        state.message = bottomStatus.attackTooLow;
        return false;
    }
    if (!options.allowDefeat && state.hp <= damage) {
        state.message = bottomStatus.hpTooLow;
        return false;
    }
    if (state.hp <= damage) {
        // A normal battle, including first-strike encounters, is also a lethal
        // game-over condition.  Resolve the damage before stopping so every
        // failure path is represented by the same hp <= 0 state invariant.
        state.hp -= damage;
        markDefeated(state, 'You lose! You were defeated in battle.');
        return false;
    }
    state.hp -= damage;
    const gold = context.goldForMonster(monster);
    state.gold += gold;
    context.remove(tile);
    for (const result of context.dispatchFloorEvents?.(state.floor, 'entity-defeated', {
        x: tile.x,
        y: tile.y,
        tile,
        entity
    }) ?? []){
        if (result.message) state.message = result.message;
        if (result.effects?.length) context.applyEffects(result.effects);
    }
    state.message = monster.partOf ? bottomStatus.defeatedPart(monster.partOf, gold) : bottomStatus.defeated(monster.name, gold);
    return true;
}

