const statePos = (floor, x, y)=>`${floor}:${x}:${y}`;
function floorFor(state) {
    return MAGIC_TOWER_CAMPAIGN.floors[state.floor] ?? MAGIC_TOWER_CAMPAIGN.floors[1];
}
function tileAt(state, x = state.x, y = state.y) {
    return floorFor(state).tiles[y]?.[x];
}
function layersAt(state, x = state.x, y = state.y, floor = state.floor) {
    return campaign_MAGIC_TOWER_CAMPAIGN.floors[floor]?.tiles[y]?.[x]?.layers ?? [];
}
function terrainAt(state, x, y) {
    const key = statePos(state.floor, x, y);
    if (state.broken.includes(key) || state.frozen.includes(key)) return TerrainId.Floor;
    return tileAt(state, x, y)?.terrain;
}
function removed(state, entity) {
    return state.removed.includes(entity.uid);
}
function entitiesAt(state, x = state.x, y = state.y) {
    return layersAt(state, x, y).slice().sort((a, b)=>a.interactionPriority - b.interactionPriority).flatMap((tile)=>tile.entities).filter((entity)=>!removed(state, entity));
}
function activeTiles(state, floor = state.floor) {
    return floorFor({
        ...state,
        floor
    }).tiles.flatMap((row)=>row).flatMap((tile)=>tile.layers).filter((tile)=>!tile.entity || !state.removed.includes(tile.entity.uid));
}
function entityAt(state, x = state.x, y = state.y) {
    return entitiesAt(state, x, y)[0];
}
function removeEntity(state, entity) {
    if (!state.removed.includes(entity.uid)) state.removed.push(entity.uid);
}
function removeAt(state, floor, x, y, kinds) {
    for (const entity of layersAt(state, x, y, floor).flatMap((tile)=>tile.entities))if (entity.x === x && entity.y === y && (!kinds || kinds.includes(entity.kind))) removeEntity(state, entity);
}
function flag(state, id) {
    if (!state.flags.includes(id)) state.flags.push(id);
}
function flagged(state, id) {
    return state.flags.includes(id);
}
function has(state, item) {
    return (state.items[item] ?? 0) > 0;
}
function gain(state, item, amount = 1) {
    state.items[item] = (state.items[item] ?? 0) + amount;
}
function spend(state, item, amount = 1) {
    state.items[item] = Math.max(0, (state.items[item] ?? 0) - amount);
}
function activeMonsters(state) {
    return activeTiles(state).flatMap((tile)=>tile.entities).filter((entity)=>entity.kind === 'monster' && !removed(state, entity));
}
function activeGates(state) {
    return activeTiles(state).flatMap((tile)=>tile.entities).filter((entity)=>entity.kind === 'gate' && !removed(state, entity));
}

