;// ./source/_components/Terminal/games/magicTower/tiles/TokenTile/collectibles/items/magicMattock.ts


class MagicMattock extends ItemTile {
    static{
        this.token = 'Mm';
    }
    static{
        this.identity = {
            id: ItemId.Mattock,
            name: 'Magic Mattock'
        };
    }
    static{
        this.display = {
            color: 'gray'
        };
    }
    static{
        this.shortcut = 'p';
    }
    static use(context) {
        if (!context.has(ItemId.Mattock)) {
            return {
                handled: false,
                movement: 'stay'
            };
        }
        const deltas = [
            [
                -1,
                0
            ],
            [
                1,
                0
            ],
            [
                0,
                -1
            ],
            [
                0,
                1
            ]
        ];
        let broke = false;
        for (const [dx, dy] of deltas){
            const target = context.findTile(context.state.floor, context.state.x + dx, context.state.y + dy);
            if (target && (target.token === '##' || target.token === '%%')) {
                context.breakAt(target.floor, target.x, target.y);
                broke = true;
            }
        }
        if (!broke) {
            return {
                handled: false,
                movement: 'stay'
            };
        }
        context.spend(ItemId.Mattock);
        context.setMessage(`Used ${this.identity.name}! The walls around you collapsed!`);
        return {
            handled: true,
            movement: 'stay'
        };
    }
}

;// ./source/_components/Terminal/games/magicTower/tiles/TokenTile/collectibles/items/snowCrystal.ts


class SnowCrystal extends ItemTile {
    static{
        this.token = 'Sn';
    }
    static{
        this.identity = {
            id: ItemId.SnowCrystal,
            name: 'Snow Crystal'
        };
    }
    static{
        this.display = {
            color: 'cyan'
        };
    }
    static{
        this.shortcut = 'i';
    }
    static use(context) {
        if (!context.has(ItemId.SnowCrystal)) {
            return {
                handled: false,
                movement: 'stay'
            };
        }
        // Actively condense nearby lava into a walkable frozen road.
        let frozen = 0;
        for (const [x, y] of [
            [
                context.state.x,
                context.state.y
            ],
            [
                context.state.x + 1,
                context.state.y
            ],
            [
                context.state.x - 1,
                context.state.y
            ],
            [
                context.state.x,
                context.state.y + 1
            ],
            [
                context.state.x,
                context.state.y - 1
            ]
        ]){
            const tile = context.findTile(context.state.floor, x, y);
            if (tile?.terrain === ids_TerrainId.Lava) {
                context.freezeAt(context.state.floor, x, y);
                frozen++;
            }
        }
        if (frozen) context.setMessage(`Used ${context.itemName(ItemId.SnowCrystal)}! The lava condensed into road!`);
        return {
            handled: Boolean(frozen),
            movement: 'stay'
        };
    }
}

