class WarpStaff extends ItemTile {
    static{
        this.token = 'Ws';
    }
    static{
        this.identity = {
            id: ItemId.WarpStaff,
            name: 'Warp Staff'
        };
    }
    static{
        this.display = {
            color: 'purple'
        };
    }
    static{
        this.amount = 3;
    }
    static{
        this.shortcut = 'j';
    }
    static use(context) {
        if (!context.has(ItemId.WarpStaff)) {
            return {
                handled: false,
                movement: 'stay'
            };
        }
        const x = 10 - context.state.x;
        const y = 10 - context.state.y;
        const target = context.findTile(context.state.floor, x, y);
        if (!target || target.terrain !== ids_TerrainId.Floor || context.tilesAt(context.state.floor, x, y).some((tile)=>tile.entity && !context.isRemoved(tile.entity))) {
            context.setMessage("Can't warp due to obstacles.");
            return {
                handled: false,
                movement: 'stay'
            };
        }
        context.state.x = x;
        context.state.y = y;
        context.spend(ItemId.WarpStaff);
        context.setMessage(`Used ${this.identity.name}! Space warped!`);
        return {
            handled: true,
            movement: 'stay'
        };
    }
}

;// ./source/_components/Terminal/games/magicTower/tiles/TokenTile/collectibles/items/wingToFlyDown.ts


class WingToFlyDown extends ItemTile {
    static{
        this.token = 'Wd';
    }
    static{
        this.identity = {
            id: ItemId.WingToFlyDown,
            name: 'Wing To Fly Down'
        };
    }
    static{
        this.display = {
            color: 'white'
        };
    }
    static{
        this.shortcut = 'd';
    }
    static use(context) {
        if (!context.has(ItemId.WingToFlyDown)) {
            return {
                handled: false,
                movement: 'stay'
            };
        }
        const sourceFloor = context.state.floor;
        // The runtime resolves the exact next floor down; undefined means the wing
        // cannot fly down from here (for example below the 0F basement).
        const targetFloor = context.flightTarget?.(sourceFloor, 'down');
        if (targetFloor == null || targetFloor < 0) {
            context.setMessage("Can't go downstairs due to obstacles.");
            return {
                handled: false,
                movement: 'stay'
            };
        }
        // The wing keeps the hero's (x, y); that tile on the target floor must be enterable.
        const landing = context.findTile(targetFloor, context.state.x, context.state.y);
        if (!landing || !landing.canEnter(context)) {
            context.setMessage("Can't go downstairs due to obstacles.");
            return {
                handled: false,
                movement: 'stay'
            };
        }
        context.travel(targetFloor, context.state.x, context.state.y);
        context.spend(ItemId.WingToFlyDown);
        context.setMessage(`Used ${this.identity.name}!`);
        return {
            handled: true,
            movement: 'stay'
        };
    }
}

