;// ./source/_components/Terminal/games/magicTower/tiles/TokenTile/collectibles/items/destructionBall.ts



class DestructionBall extends ItemTile {
    static{
        this.token = 'Db';
    }
    static{
        this.identity = {
            id: ItemId.Bomb,
            name: 'Destruction Ball'
        };
    }
    static{
        this.display = {
            color: 'red'
        };
    }
    static{
        this.shortcut = 'b';
    }
    static use(context) {
        if (!context.has(ItemId.Bomb)) {
            return {
                handled: false,
                movement: 'stay'
            };
        }
        const victims = [
            [
                1,
                0
            ],
            [
                -1,
                0
            ],
            [
                0,
                1
            ],
            [
                0,
                -1
            ]
        ].flatMap(([dx, dy])=>context.tilesAt(context.state.floor, context.state.x + dx, context.state.y + dy).filter((tile)=>tile instanceof MonsterTile));
        if (!victims.length) {
            return {
                handled: false,
                movement: 'stay'
            };
        }
        const bombable = victims.filter((tile)=>tile.bombable);
        if (!bombable.length) {
            return {
                handled: false,
                movement: 'stay'
            };
        }
        context.spend(ItemId.Bomb);
        let gold = 0;
        for (const victim of bombable){
            // The Destruction Ball grants the monster's base gold, but it is not a
            // battle reward, so Lucky Coin must not modify it.
            gold += context.goldForMonster(victim.monster, false);
            context.remove(victim);
            for (const result of context.dispatchFloorEvents?.(context.state.floor, 'entity-defeated', {
                x: victim.x,
                y: victim.y,
                tile: victim,
                entity: victim.entity
            }) ?? []){
                if (result.message) context.setMessage(result.message);
                if (result.effects?.length) context.applyEffects(result.effects);
            }
        }
        context.state.gold += gold;
        context.setMessage(`Used ${this.identity.name}! The enemies around you were liquidated!`);
        // Destruction Ball changes the world but does not move the hero; do not retrigger a
        // positional magic field merely because an adjacent monster was removed.
        context.afterWorldChange(false);
        return {
            handled: true,
            movement: 'stay'
        };
    }
}

