;// ./source/_components/Terminal/games/magicTower/tiles/TokenTile/collectibles/items/orbOfFlight.ts





class OrbOfFlight extends ItemTile {
    static{
        this.token = 'Of';
    }
    static{
        this.identity = {
            id: ItemId.OrbOfFlight,
            name: 'Orb of Flight'
        };
    }
    static{
        this.display = {
            color: 'cyan'
        };
    }
    static{
        this.shortcut = 'g';
    }
    static{
        this.usableWithoutInventory = true;
    }
    static availableFloors(visited, currentFloor, filter) {
        return (filter?.(visited) ?? visited).filter((floor)=>floor === currentFloor || campaign_MAGIC_TOWER_CAMPAIGN.floors[floor]?.navigation.orbOfFlight !== false).slice().sort((a, b)=>a - b);
    }
    static use(context) {
        if (!context.has(ItemId.OrbOfFlight)) {
            return {
                handled: false,
                movement: 'stay'
            };
        }
        if (!context.isAdjacentToStairs()) {
            context.setMessage("Can't use Orb of Flight unless next to stairs!");
            return {
                handled: false,
                movement: 'stay'
            };
        }
        context.state.overlay = 'orbOfFlight';
        context.setMessage("There're stairs.");
        // The current floor is always listed (even 0F/44F, which other floors
        // cannot fly into), so the cursor lands on it when opening the panel here.
        const floors = OrbOfFlight.availableFloors(context.state.visited, context.state.floor);
        context.state.menuIndex = Math.max(0, floors.indexOf(context.state.floor));
        return {
            handled: true,
            movement: 'stay'
        };
    }
    static renderPanel(state) {
        const floors = OrbOfFlight.availableFloors(state.visited, state.floor);
        const start = Math.max(0, Math.min(floors.length - 9, state.menuIndex - 4));
        return [
            ansi.W + 'Orb of Flight' + ansi.X,
            ansi.D + 'Up/Down select  Enter travel' + ansi.X,
            ...selectableList(floors.slice(start, start + 9).map((floor)=>`F${String(floor).padStart(2, '0')} Floor ${floor}`), state.menuIndex - start)
        ].slice(0, 11);
    }
}

