class Dragon extends MonsterTile {
    static{
        this.token = 'DR';
    }
    static{
        this.identity = {
            id: RoleId.Dragon,
            name: 'Dragon'
        };
    }
    static{
        this.display = {
            color: 'red'
        };
    }
    static{
        this.monster = {
            hp: 1500,
            attack: 600,
            defense: 250,
            gold: 800,
            dragonSlayerVulnerable: true,
            destructionBallImmune: true
        };
    }
    get isHeart() {
        return this.floor === 35 && this.x === 5 && this.y === 6;
    }
    canEnter(context) {
        if (this.floor === 35 && !this.isHeart && this.entity && !context.isRemoved(this.entity)) {
            return false;
        }
        return super.canEnter(context);
    }
    enter(context) {
        const result = super.enter(context);
        if (result.handled && this.isHeart && this.entity && context.isRemoved(this.entity)) {
            for (const tile of context.activeTiles(35))if (tile.token === Dragon.token && tile.x >= 4 && tile.x <= 6 && tile.y >= 4 && tile.y <= 6) context.remove(tile);
        }
        return result;
    }
}

