/** Binds a floor-owned interaction to an NPC token at an exact coordinate. */ function floorNpc(id, at, options) {
    return {
        id,
        at,
        hooks: {
            'before-enter': {
                when: (context, payload)=>{
                    const tile = payload?.tile;
                    return Boolean(tile && tile.layers.some((layer)=>layer.token === options.token && Boolean(layer.entity) && !context.isRemoved(layer.entity)));
                },
                run: (context, payload)=>{
                    const destination = payload?.tile;
                    const npc = destination?.layers.find((layer)=>layer.token === options.token);
                    const statusMessage = npc?.statusMessage?.();
                    if (statusMessage) context.setMessage(statusMessage);
                    const dialog = options.open(context);
                    if (!dialog) return {
                        handled: false,
                        movement: 'step'
                    };
                    context.openFloorDialog(dialog);
                    return {
                        handled: true,
                        movement: 'stay'
                    };
                }
            },
            'dialog-choice': options.onChoice ? {
                run: (context, payload)=>options.onChoice(context, Number(payload?.choice ?? 0), payload?.flowId) ?? {
                        handled: true,
                        movement: 'stay'
                    }
            } : undefined,
            'dialog-complete': options.onComplete ? {
                run: (context, payload)=>options.onComplete(context, payload?.flowId) ?? {
                        handled: true,
                        movement: 'stay'
                    }
            } : undefined
        }
    };
}
