class Altar extends NpcTile {
    static{
        this.token = '$A';
    }
    static{
        this.identity = {
            id: RoleId.Altar,
            name: 'Altar'
        };
    }
    static{
        this.display = {
            color: 'blue'
        };
    }
    static{
        this.dialog = 'Choose one improvement. Every purchase raises the price at every altar.';
    }
    static cost(state) {
        const n = state.shopPurchases + 1;
        return 10 * n * (n - 1) + 20;
    }
    static values(floor, shopPurchases) {
        const stage = Math.floor(floor / 10) + 1;
        return {
            hp: (shopPurchases + 1) * 100,
            attack: stage * 2,
            defense: stage * 4
        };
    }
    static options(state) {
        const values = Altar.values(state.floor, state.shopPurchases);
        return [
            `HP+${values.hp}`,
            `ATK+${values.attack}`,
            `DEF+${values.defense}`,
            'Esc'
        ];
    }
    static buy(state, choice) {
        const price = Altar.cost(state);
        if (state.gold < price) {
            return true;
        }
        const values = Altar.values(state.floor, state.shopPurchases);
        state.gold -= price;
        state.shopPurchases++;
        if (choice === 0) state.hp += values.hp;
        else if (choice === 1) state.attack += values.attack;
        else state.defense += values.defense;
        state.message = `There's an ${Altar.identity.name.toLowerCase()}.`;
        return true;
    }
    /**
   * The Tower Altar as a dialog NPC: walking onto the `$A` cell opens the
   * offer, and each purchase re-opens it so the hero can keep upgrading while
   * standing here. Esc closes it.
   */ static floorEvent(id, at) {
        const flowId = `${id}-offer`;
        const offer = (state)=>({
                speaker: 'Tower Altar',
                text: `${Altar.dialog}\nCurrent price: ${Altar.cost(state)} gold.`,
                options: Altar.options(state),
                flowId
            });
        return floorNpc(id, at, {
            token: '$A',
            open: (context)=>offer(context.state),
            onChoice: (context, choice, chosenFlowId)=>{
                if (chosenFlowId === flowId) {
                    if (choice === 3) return {
                        handled: true,
                        movement: 'stay'
                    };
                    const menuIndex = context.state.menuIndex;
                    Altar.buy(context.state, choice);
                    context.openFloorDialog(offer(context.state));
                    context.state.menuIndex = menuIndex;
                }
                return {
                    handled: true,
                    movement: 'stay'
                };
            }
        });
    }
}

