const TIME_TUNNEL_OPENING = [
    [
        5,
        1
    ],
    [
        5,
        2
    ],
    [
        5,
        3
    ]
];
/** The wall cells that become the 24F route after the two prerequisite scenes. */ const FLOOR_24_TIME_TUNNEL_OPENING = (/* unused pure expression or super */ null && (TIME_TUNNEL_OPENING));
const floor24 = new MagicTowerFloor({
    id: 24,
    source: floorMap`
......................
......##########......
....##############....
..##################..
..######......######..
..######......######..
..######......######..
..########R|########..
....######..######....
..^^..####..####......
vv^v..................
`,
    events: [
        {
            id: 'f24-time-tunnel',
            hooks: {
                'world-change': {
                    once: true,
                    when: (context)=>context.flagged('f25-gm-defeated') && context.flagged('f26-pr-rescued') && !context.flagged('f24-time-tunnel'),
                    run: (context)=>{
                        for (const [x, y] of TIME_TUNNEL_OPENING)context.breakAt(24, x, y);
                        // The side walls appear only when the two prerequisite scenes
                        // complete, leaving the centre as the sole route to Floor 50.
                        context.replaceTile('##', 24, 4, 0);
                        context.replaceTile('##', 24, 6, 0);
                        context.flag('f24-time-tunnel');
                        context.setMessage('The road turned into a wall!');
                        return {
                            handled: true,
                            movement: 'stay'
                        };
                    }
                }
            }
        },
        // The route stays an ordinary floor cell; stepping on the top cell
        // carries the hero straight to Floor 50's landing marker.
        floorEnter('f24-to-floor-50', [
            5,
            0
        ], (context)=>{
            if (!context.flagged('f24-time-tunnel')) return;
            const landing = context.findLanding(50, 24);
            context.travel(50, landing?.x ?? 5, landing?.y ?? 6);
            // This route teleports directly instead of using a stairs Tile, so it
            // must explicitly deliver the normal arrival hook for 50F's reveal.
            context.dispatchFloorEvents?.(50, 'floor-enter', {
                fromFloor: 24
            });
        })
    ]
});

