;// ./source/_components/Terminal/commands/games.ts




function printGames(context) {
    context.writeln(ansi.W + 'Available games' + ansi.X);
    context.writeln(ansi.D + 'Use games <id> to start a game; use games saves to inspect saves.' + ansi.X);
    for (const line of gameListText())context.writeln(line);
    context.writeln(ansi.D + `${GAME_DEFINITIONS.length} games available.` + ansi.X);
}
function printSlots(context, gameId) {
    if (!gameId) {
        context.writeln(ansi.R + 'games saves: provide a valid game ID.' + ansi.X);
        return;
    }
    const saves = createGameStorage().load(gameId);
    context.writeln(ansi.W + `${gameId} saves (1 auto + ${GAME_MANUAL_SLOT_COUNT} manual)` + ansi.X);
    context.writeln(`Auto Save: ${saves.auto ? new Date(saves.auto.updatedAt).toLocaleString() : ansi.D + 'empty' + ansi.X}`);
    for(let index = 0; index < GAME_MANUAL_SLOT_COUNT; index++){
        const save = saves.manual[index];
        context.writeln(`Manual Save ${index + 1}: ${save ? new Date(save.updatedAt).toLocaleString() : ansi.D + 'empty' + ansi.X}`);
    }
}
async function runGames(context, args, inputState, signal) {
    const first = args[0]?.toLowerCase();
    if (!first) {
        printGames(context);
        return;
    }
    if (first === '--help' || first === '-h') {
        context.writeln(ansi.W + 'games' + ansi.X + ': list or start terminal games.');
        context.writeln('gameslist available games');
        context.writeln('games <id> start a game');
        context.writeln('games saves <id> show the auto save and four manual slots');
        context.writeln('Press Esc to pause and Ctrl+C to exit a game.');
        return;
    }
    if (first === 'saves') {
        printSlots(context, resolveGameId(args[1]));
        return;
    }
    const id = resolveGameId(first);
    if (!id) {
        context.writeln(ansi.R + `games: unknown game '${args[0]}'.` + ansi.X);
        printGames(context);
        return;
    }
    const storage = createGameStorage();
    const definition = createGameDefinition(id, storage);
    const session = definition.create({
        term: context.term,
        signal,
        write: context.write,
        storage,
        mode: 'solo',
        game: id
    });
    inputState.activeGame = session;
    try {
        await session.done;
    } finally{
        if (inputState.activeGame === session) inputState.activeGame = null;
    }
}

